// Procedural texture atlas. Every pixel here is generated by code at startup:
// no original game assets are used. Tiles are 16x16 and packed in a 32x32 grid.

export const TILE = 16;
export const ATLAS_TILES = 32;
export const ATLAS_SIZE = TILE * ATLAS_TILES;

const tileIndex = new Map();
const tileList = [];

function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashStr(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

class Px {
  constructor(name) {
    this.d = new Uint8ClampedArray(TILE * TILE * 4);
    this.r = rng(hashStr(name));
  }
  set(x, y, c, a = 255) {
    if (x < 0 || y < 0 || x >= TILE || y >= TILE) return;
    const i = (y * TILE + x) * 4;
    this.d[i] = c[0]; this.d[i + 1] = c[1]; this.d[i + 2] = c[2]; this.d[i + 3] = c.length > 3 ? c[3] : a;
  }
  get(x, y) {
    const i = (y * TILE + x) * 4;
    return [this.d[i], this.d[i + 1], this.d[i + 2], this.d[i + 3]];
  }
  clear(x, y) { this.set(x, y, [0, 0, 0, 0]); }
  fill(c) { for (let y = 0; y < TILE; y++) for (let x = 0; x < TILE; x++) this.set(x, y, c); }
  // per-pixel brightness jitter around a base color
  noise(base, amt = 18) {
    for (let y = 0; y < TILE; y++) for (let x = 0; x < TILE; x++) {
      const k = (this.r() - 0.5) * 2 * amt;
      this.set(x, y, [base[0] + k, base[1] + k, base[2] + k]);
    }
  }
  speckle(c, chance, amt = 10) {
    for (let y = 0; y < TILE; y++) for (let x = 0; x < TILE; x++) {
      if (this.r() < chance) { const k = (this.r() - 0.5) * amt; this.set(x, y, [c[0] + k, c[1] + k, c[2] + k]); }
    }
  }
  blob(cx, cy, rad, c, amt = 12) {
    for (let y = -rad; y <= rad; y++) for (let x = -rad; x <= rad; x++) {
      if (x * x + y * y <= rad * rad + this.r() * 1.5) {
        const k = (this.r() - 0.5) * amt;
        this.set(cx + x, cy + y, [c[0] + k, c[1] + k, c[2] + k]);
      }
    }
  }
  rect(x0, y0, w, h, c) { for (let y = y0; y < y0 + h; y++) for (let x = x0; x < x0 + w; x++) this.set(x, y, c); }
  tint(m) {
    for (let i = 0; i < this.d.length; i += 4) { this.d[i] *= m[0]; this.d[i + 1] *= m[1]; this.d[i + 2] *= m[2]; }
  }
  // draw a 16-row string sprite. Each char maps to a palette color, '.' = transparent
  sprite(rows, pal, ox = 0, oy = 0) {
    for (let y = 0; y < rows.length; y++) for (let x = 0; x < rows[y].length; x++) {
      const ch = rows[y][x];
      if (ch === '.' || ch === ' ') continue;
      const c = pal[ch];
      if (c) this.set(ox + x, oy + y, c);
    }
  }
}

function shade(c, f) { return [c[0] * f, c[1] * f, c[2] * f]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }

function def(name, fn) {
  tileIndex.set(name, tileList.length);
  tileList.push({ name, fn });
}

export function tex(name) {
  const i = tileIndex.get(name);
  if (i === undefined) throw new Error('missing texture ' + name);
  return i;
}
export function hasTex(name) { return tileIndex.has(name); }

// ---------------------------------------------------------------- materials
const STONE = [125, 125, 125];
const DIRT = [134, 96, 67];
const GRASS = [104, 160, 64];
const SAND = [219, 207, 163];
const OAK = [160, 130, 80];
const COBBLE = [118, 118, 118];

function stone(p, base = STONE) {
  p.noise(base, 14);
  for (let i = 0; i < 9; i++) {
    const x = (p.r() * 16) | 0, y = (p.r() * 16) | 0, l = 2 + ((p.r() * 3) | 0);
    for (let j = 0; j < l; j++) p.set(x + j, y, shade(base, 0.82));
  }
}
function ore(p, c, c2) {
  stone(p);
  const n = 4 + ((p.r() * 2) | 0);
  for (let i = 0; i < n; i++) {
    const x = 2 + ((p.r() * 12) | 0), y = 2 + ((p.r() * 12) | 0);
    p.set(x, y, c); p.set(x + 1, y, c2 || shade(c, 0.8)); p.set(x, y + 1, shade(c, 0.85)); if (p.r() < 0.6) p.set(x + 1, y + 1, c);
  }
}
function dirt(p) {
  p.noise(DIRT, 16);
  p.speckle([110, 78, 54], 0.12);
  p.speckle([150, 112, 80], 0.08);
}
function cobble(p, base = COBBLE, moss = false) {
  p.noise(shade(base, 0.7), 6);
  const stones = [[1, 1, 5, 4], [7, 0, 6, 4], [13, 1, 3, 5], [0, 6, 4, 5], [5, 5, 6, 5], [11, 7, 5, 4], [0, 12, 6, 4], [7, 11, 5, 5], [12, 12, 4, 4]];
  for (const [x, y, w, h] of stones) {
    const f = 0.85 + p.r() * 0.3;
    for (let yy = 0; yy < h - 1; yy++) for (let xx = 0; xx < w - 1; xx++) {
      const k = (p.r() - 0.5) * 16;
      let c = shade(base, f); c = [c[0] + k, c[1] + k, c[2] + k];
      if (yy === 0 || xx === 0) c = shade(c, 1.15);
      if (moss && p.r() < 0.35) c = [70 + k, 110 + k, 60 + k];
      p.set(x + xx, y + yy, c);
    }
  }
}
function planks(p, base = OAK) {
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    const band = y % 4 === 3;
    const grain = Math.sin((x + (y >> 2) * 5) * 1.3) * 6 + (p.r() - 0.5) * 10;
    let c = shade(base, band ? 0.72 : 1);
    p.set(x, y, [c[0] + grain, c[1] + grain, c[2] + grain]);
  }
  for (let r = 0; r < 4; r++) { const x = (r * 7 + 3) % 16; p.set(x, r * 4 + 1, shade(base, 0.7)); p.set(x, r * 4 + 2, shade(base, 0.7)); }
}
function logSide(p, bark, dark) {
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    const stripe = (x % 4 === 0 || (x + ((y >> 3) & 1)) % 5 === 0) ? 0.75 : 1;
    const k = (p.r() - 0.5) * 14;
    const c = shade(bark, stripe);
    p.set(x, y, [c[0] + k, c[1] + k, c[2] + k]);
  }
  if (dark) for (let i = 0; i < 10; i++) p.set((p.r() * 16) | 0, (p.r() * 16) | 0, dark);
}
function logTop(p, bark, inner) {
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    const dx = x - 7.5, dy = y - 7.5, d = Math.max(Math.abs(dx), Math.abs(dy));
    let c;
    if (d > 6.5) c = bark; else c = shade(inner, (Math.floor(d) % 2 === 0) ? 1 : 0.85);
    const k = (p.r() - 0.5) * 8;
    p.set(x, y, [c[0] + k, c[1] + k, c[2] + k]);
  }
}
function leaves(p, base) {
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    if (p.r() < 0.2) { p.clear(x, y); continue; }
    const k = (p.r() - 0.5) * 40;
    p.set(x, y, [base[0] + k, base[1] + k, base[2] + k]);
  }
}
function wool(p, c) {
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    const k = (p.r() - 0.5) * 14 + (((x + y) & 3) === 0 ? -8 : 0);
    p.set(x, y, [c[0] + k, c[1] + k, c[2] + k]);
  }
}
function metalBlock(p, c) {
  p.noise(c, 6);
  for (let i = 0; i < 16; i++) { p.set(i, 0, shade(c, 1.25)); p.set(0, i, shade(c, 1.2)); p.set(i, 15, shade(c, 0.7)); p.set(15, i, shade(c, 0.75)); }
  for (let i = 2; i < 14; i++) if ((i & 3) === 1) { p.set(i, i, shade(c, 1.3)); p.set(i + 1, i, shade(c, 1.15)); }
}
function bricks(p, brick, mortar, rows = 4) {
  const h = 16 / rows;
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    const row = Math.floor(y / h);
    const off = (row & 1) ? h : 0;
    const mortarLine = y % h === h - 1 || ((x + off) % (h * 2)) === 0;
    const k = (p.r() - 0.5) * 16;
    const c = mortarLine ? mortar : brick;
    p.set(x, y, [c[0] + k, c[1] + k, c[2] + k]);
  }
}
function plantCross(p, stemCol, flowerCol, centerCol) {
  for (let y = 7; y < 16; y++) p.set(7 + ((y & 4) ? 1 : 0), y, stemCol);
  p.set(6, 11, stemCol); p.set(5, 10, stemCol); p.set(9, 12, stemCol); p.set(10, 11, stemCol);
  if (flowerCol) {
    p.blob(7, 5, 2, flowerCol, 20);
    if (centerCol) p.set(7, 5, centerCol);
  }
}

const DYE_COLORS = [
  [222, 222, 222], [219, 125, 62], [179, 80, 188], [107, 138, 201], [177, 166, 39], [65, 174, 56], [208, 132, 153], [64, 64, 64],
  [154, 161, 161], [46, 110, 137], [126, 61, 181], [46, 56, 141], [79, 50, 31], [53, 70, 27], [150, 52, 48], [25, 22, 22]
];
export const WOOL_COLORS = DYE_COLORS;

// ---------------------------------------------------------------- block tiles
def('stone', p => stone(p));
def('grass_top', p => { p.noise(GRASS, 22); p.speckle([86, 140, 50], 0.2); });
def('grass_side', p => {
  dirt(p);
  for (let x = 0; x < 16; x++) {
    const h = 3 + ((p.r() * 3) | 0);
    for (let y = 0; y < h; y++) { const k = (p.r() - 0.5) * 20; p.set(x, y, [GRASS[0] + k, GRASS[1] + k, GRASS[2] + k]); }
  }
});
def('grass_side_snow', p => {
  dirt(p);
  for (let x = 0; x < 16; x++) { const h = 3 + ((p.r() * 3) | 0); for (let y = 0; y < h; y++) p.set(x, y, [240 - p.r() * 20, 245 - p.r() * 15, 250]); }
});
def('dirt', p => dirt(p));
def('cobblestone', p => cobble(p));
def('mossy_cobblestone', p => cobble(p, COBBLE, true));
def('planks', p => planks(p));
def('bedrock', p => { p.noise([70, 70, 70], 35); p.speckle([30, 30, 30], 0.25); p.speckle([140, 140, 140], 0.1); });
def('sand', p => { p.noise(SAND, 12); p.speckle([200, 188, 140], 0.15); });
def('gravel', p => {
  p.noise([128, 122, 120], 10);
  for (let i = 0; i < 28; i++) p.blob((p.r() * 16) | 0, (p.r() * 16) | 0, 1, p.r() < 0.5 ? [100, 92, 90] : [160, 152, 150], 20);
});
def('sandstone_top', p => { p.noise([216, 203, 156], 8); });
def('sandstone_side', p => {
  p.noise([216, 203, 156], 8);
  for (let x = 0; x < 16; x++) { p.set(x, 3, [196, 182, 134]); p.set(x, 4, [226, 214, 170]); p.set(x, 11, [196, 182, 134]); }
});
def('sandstone_bottom', p => { p.noise([210, 196, 148], 12); for (let x = 0; x < 16; x++) p.set(x, 12, [190, 175, 128]); });
def('coal_ore', p => ore(p, [40, 40, 40]));
def('iron_ore', p => ore(p, [216, 175, 147]));
def('gold_ore', p => ore(p, [250, 230, 80]));
def('diamond_ore', p => ore(p, [100, 230, 225]));
def('redstone_ore', p => ore(p, [200, 20, 20]));
def('lapis_ore', p => ore(p, [30, 70, 180]));
def('log_oak', p => logSide(p, [104, 82, 50], [80, 62, 36]));
def('log_spruce', p => logSide(p, [60, 42, 24], [44, 30, 16]));
def('log_birch', p => {
  p.noise([220, 220, 210], 8);
  for (let i = 0; i < 10; i++) { const x = (p.r() * 14) | 0, y = (p.r() * 16) | 0; p.set(x, y, [50, 50, 45]); p.set(x + 1, y, [70, 70, 60]); }
});
def('log_top', p => logTop(p, [104, 82, 50], [180, 146, 90]));
def('leaves_oak', p => leaves(p, [60, 140, 40]));
def('leaves_spruce', p => leaves(p, [50, 96, 60]));
def('leaves_birch', p => leaves(p, [110, 150, 70]));
def('glass', p => {
  for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) {
    const edge = x === 0 || y === 0 || x === 15 || y === 15;
    if (edge) p.set(x, y, [200, 230, 240]);
    else if ((x - y === 3 || x - y === 4) && x > 2 && x < 9) p.set(x, y, [255, 255, 255, 180]);
    else p.clear(x, y);
  }
});
def('lapis_block', p => { p.noise([38, 67, 138], 18); p.speckle([60, 100, 190], 0.2); });
def('gold_block', p => metalBlock(p, [245, 210, 60]));
def('iron_block', p => metalBlock(p, [220, 220, 220]));
def('diamond_block', p => metalBlock(p, [110, 225, 220]));
def('bricks', p => bricks(p, [150, 74, 58], [170, 160, 150]));
def('stone_bricks', p => bricks(p, [122, 122, 122], [90, 90, 90], 2));
def('nether_bricks', p => bricks(p, [60, 28, 34], [30, 14, 18]));
def('netherrack', p => { p.noise([110, 52, 50], 20); p.speckle([140, 70, 66], 0.15); p.speckle([80, 34, 34], 0.15); });
def('obsidian', p => { p.noise([22, 16, 32], 8); p.speckle([60, 40, 90], 0.12); });
def('glowing_obsidian', p => { p.noise([110, 20, 20], 25); p.speckle([255, 140, 40], 0.18); p.speckle([40, 10, 20], 0.12); });
