def('sapling_spruce', p => { plantCross(p, [60, 40, 20], null); for (let y = 2; y < 12; y++) { const w = (y - 1) >> 1; for (let x = -w; x <= w; x++) p.set(7 + x, y, [50, 96, 60 + p.r() * 20]); } });
def('sapling_birch', p => { plantCross(p, [200, 200, 190], null); p.blob(7, 6, 4, [110, 150, 70], 30); });
