def('mushroom_red', p => { p.rect(7, 9, 2, 6, [220, 210, 190]); p.rect(4, 5, 8, 4, [210, 30, 30]); p.rect(5, 4, 6, 1, [220, 40, 40]); p.set(5, 6, [255, 255, 255]); p.set(9, 5, [255, 255, 255]); p.set(10, 7, [255, 255, 255]); });
def('torch', p => {
  p.rect(7, 6, 2, 10, [140, 100, 50]);
  p.rect(7, 5, 2, 1, [255, 255, 160]); p.rect(7, 4, 2, 1, [255, 200, 50]); p.set(7, 3, [255, 150, 40]);
});
def('ladder', p => {
  for (let y = 0; y < 16; y++) { p.set(2, y, [130, 95, 50]); p.set(3, y, [110, 80, 40]); p.set(12, y, [130, 95, 50]); p.set(13, y, [110, 80, 40]); }
  for (const y of [2, 6, 10, 14]) for (let x = 2; x < 14; x++) p.set(x, y, [150, 112, 60]);
});
def('door_wood_upper', p => {
  planks(p, [150, 112, 60]);
  p.rect(3, 3, 4, 4, [170, 220, 240, 0]); p.rect(9, 3, 4, 4, [170, 220, 240, 0]);
  for (let i = 0; i < 16; i++) { p.set(0, i, [100, 70, 35]); p.set(15, i, [100, 70, 35]); p.set(i, 0, [100, 70, 35]); }
});
def('door_wood_lower', p => {
  planks(p, [150, 112, 60]);
  for (let i = 0; i < 16; i++) { p.set(0, i, [100, 70, 35]); p.set(15, i, [100, 70, 35]); p.set(i, 15, [100, 70, 35]); }
  p.rect(3, 3, 10, 4, [130, 96, 50]); p.rect(3, 9, 10, 4, [130, 96, 50]);
  p.set(12, 1, [60, 60, 60]); p.set(12, 0, [60, 60, 60]);
});
def('trapdoor', p => {
  planks(p, [150, 112, 60]);
  for (let i = 0; i < 16; i++) { p.set(0, i, [100, 70, 35]); p.set(15, i, [100, 70, 35]); p.set(i, 0, [100, 70, 35]); p.set(i, 15, [100, 70, 35]); }
  p.rect(3, 3, 4, 4, [0, 0, 0, 0]); p.rect(9, 3, 4, 4, [0, 0, 0, 0]); p.rect(3, 9, 4, 4, [0, 0, 0, 0]); p.rect(9, 9, 4, 4, [0, 0, 0, 0]);
});
def('wheat_0', p => { for (let x = 2; x < 15; x += 3) { p.set(x, 15, [60, 160, 40]); p.set(x, 14, [70, 170, 50]); } });
for (let s = 1; s < 8; s++) def('wheat_' + s, p => {
  const h = 2 + s * 1.7;
  for (let x = 1; x < 16; x += 2) for (let y = 0; y < h; y++) {
    const ripe = s === 7;
    const c = ripe ? [190 + p.r() * 30, 160 + p.r() * 30, 50] : [60 + s * 12, 160 - s * 4, 40];
    p.set(x + (y > h * 0.6 && (x & 2) ? 1 : 0), 15 - y, c);
  }
});
def('farmland_dry', p => { dirt(p); for (let y = 0; y < 16; y += 4) for (let x = 0; x < 16; x++) p.set(x, y, [100, 70, 48]); });
def('farmland_wet', p => { p.noise([86, 58, 38], 10); for (let y = 0; y < 16; y += 4) for (let x = 0; x < 16; x++) p.set(x, y, [62, 40, 26]); });
def('snow', p => { p.noise([240, 245, 250], 6); });
def('ice', p => { p.noise([150, 180, 250], 10); for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) { const c = p.get(x, y); p.set(x, y, [c[0], c[1], c[2], 170]); } for (let i = 0; i < 6; i++) p.set(3 + i, 2 + i, [220, 235, 255, 200]); });
def('cactus_side', p => {
  p.fill([0, 0, 0, 0]);
  for (let y = 0; y < 16; y++) for (let x = 1; x < 15; x++) { const k = (p.r() - 0.5) * 20; p.set(x, y, [20 + k, 120 + k, 30 + k]); }
  for (let y = 1; y < 16; y += 4) { p.set(1, y, [220, 220, 180]); p.set(14, y + 2, [220, 220, 180]); p.set(5, y + 1, [10, 80, 20]); p.set(10, y + 3, [10, 80, 20]); }
});
def('cactus_top', p => { p.fill([0, 0, 0, 0]); for (let y = 1; y < 15; y++) for (let x = 1; x < 15; x++) p.set(x, y, [40 + p.r() * 20, 140, 50]); p.rect(6, 6, 4, 4, [140, 170, 90]); });
def('cactus_bottom', p => { p.fill([0, 0, 0, 0]); for (let y = 1; y < 15; y++) for (let x = 1; x < 15; x++) p.set(x, y, [150, 170, 110]); });
def('clay', p => { p.noise([160, 166, 178], 8); });
def('sugarcane', p => {
  for (const x of [3, 8, 12]) for (let y = 0; y < 16; y++) {
    const knot = (y + x) % 6 === 0;
    p.set(x, y, knot ? [160, 200, 110] : [120, 180, 80]); p.set(x + 1, y, knot ? [140, 180, 90] : [100, 160, 64]);
  }
  p.set(5, 3, [100, 170, 70]); p.set(6, 2, [100, 170, 70]); p.set(10, 8, [100, 170, 70]);
});
def('pumpkin_top', p => { p.noise([200, 120, 20], 10); for (let x = 0; x < 16; x += 4) for (let y = 0; y < 16; y++) p.set(x, y, [170, 96, 10]); p.rect(6, 6, 4, 4, [110, 90, 40]); });
def('pumpkin_side', p => { p.noise([210, 125, 22], 10); for (let x = 1; x < 16; x += 4) for (let y = 0; y < 16; y++) p.set(x, y, [176, 100, 12]); });
def('pumpkin_face', p => {
  p.noise([210, 125, 22], 10); for (let x = 1; x < 16; x += 4) for (let y = 0; y < 16; y++) p.set(x, y, [176, 100, 12]);
  p.rect(3, 4, 3, 3, [40, 20, 0]); p.rect(10, 4, 3, 3, [40, 20, 0]); p.rect(3, 10, 10, 2, [40, 20, 0]); p.rect(5, 12, 2, 1, [40, 20, 0]); p.rect(9, 12, 2, 1, [40, 20, 0]);
});
def('melon_side', p => {
  p.noise([110, 150, 30], 10);
  for (let x = 0; x < 16; x += 3) for (let y = 0; y < 16; y++) if (p.r() < 0.85) p.set(x, y, [70, 110, 20]);
});
def('melon_top', p => { p.noise([110, 150, 30], 10); p.blob(8, 8, 3, [90, 130, 30]); for (let a = 0; a < 6; a++) { p.set(8 + Math.round(Math.cos(a) * 6), 8 + Math.round(Math.sin(a) * 6), [70, 110, 20]); } });
for (let s = 0; s < 8; s++) def('stem_' + s, p => {
  const h = 2 + s * 2;
  const c = s === 7 ? [180, 140, 40] : [80 + s * 12, 160 - s * 6, 40];
  for (let y = 0; y < h; y++) p.set(7 + (y & 1), 15 - y, c);
  if (s > 3) { p.set(6, 15 - h + 2, c); p.set(9, 15 - h + 3, c); }
});
def('stem_connected', p => {
  for (let y = 4; y < 16; y++) p.set(7, y, [180, 140, 40]);
  for (let x = 7; x < 16; x++) p.set(x, 4 + ((x - 7) >> 2), [180, 140, 40]);
});
def('cobweb', p => {
  for (let i = 0; i < 16; i++) { p.set(i, i, [230, 230, 230, 220]); p.set(15 - i, i, [230, 230, 230, 220]); p.set(i, 8, [220, 220, 220, 200]); p.set(8, i, [220, 220, 220, 200]); }
  for (let a = 0; a < 40; a++) { const ang = a / 40 * Math.PI * 2; for (const r of [3, 6]) p.set(8 + Math.round(Math.cos(ang) * r), 8 + Math.round(Math.sin(ang) * r), [210, 210, 210, 180]); }
});
def('bed_head_top', p => { wool(p, [170, 30, 30]); p.rect(1, 1, 14, 6, [235, 235, 235]); });
def('bed_foot_top', p => { wool(p, [170, 30, 30]); });
def('bed_side_head', p => { p.fill([0, 0, 0, 0]); p.rect(0, 7, 16, 3, [170, 30, 30]); p.rect(0, 10, 16, 3, [150, 112, 60]); p.rect(0, 13, 2, 3, [120, 90, 50]); p.rect(0, 7, 6, 2, [235, 235, 235]); });
def('bed_side_foot', p => { p.fill([0, 0, 0, 0]); p.rect(0, 7, 16, 3, [170, 30, 30]); p.rect(0, 10, 16, 3, [150, 112, 60]); p.rect(14, 13, 2, 3, [120, 90, 50]); });
def('bed_end', p => { p.fill([0, 0, 0, 0]); p.rect(0, 7, 16, 3, [170, 30, 30]); p.rect(0, 10, 16, 3, [150, 112, 60]); p.rect(0, 13, 2, 3, [120, 90, 50]); p.rect(14, 13, 2, 3, [120, 90, 50]); });
def('water', p => { for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) { const k = Math.sin((x + y * 0.5) * 0.9) * 10 + (p.r() - 0.5) * 10; p.set(x, y, [40 + k, 80 + k, 210 + k, 170]); } });
def('lava', p => { for (let y = 0; y < 16; y++) for (let x = 0; x < 16; x++) { const k = Math.sin(x * 0.7) * Math.cos(y * 0.6) * 30 + (p.r() - 0.5) * 20; p.set(x, y, [230 + k, 110 + k * 1.5, 20]); } });
def('fire', p => { for (let x = 0; x < 16; x++) { const h = 6 + p.r() * 10; for (let y = 0; y < h; y++) p.set(x, 15 - y, mix([255, 230, 60], [220, 50, 10], y / h)); } });
for (let i = 0; i < 10; i++) def('destroy_' + i, p => {
  const n = (i + 1) * 9;
  for (let k = 0; k < n; k++) {
    let x = (p.r() * 16) | 0, y = (p.r() * 16) | 0;
    const len = 2 + ((p.r() * 3) | 0);
    for (let j = 0; j < len; j++) { p.set(x, y, [0, 0, 0, 150]); x += p.r() < 0.5 ? 1 : 0; y += p.r() < 0.5 ? 1 : -1; }
  }
});
def('white', p => p.fill([255, 255, 255]));
def('cloud', p => p.fill([255, 255, 255, 200]));

